def sum_list(nums):
    total = 0
    for n in nums:
        total += n
    return total

print(sum_list([1, 2, 3]))  #

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

print(factorial(4))  #

def squares(xs):
    return [x * x for x in xs]

print(squares([1, 2, 3]))  #

def find_max(values):
    best = values[0]
    for v in values:
        if v > best:
            best = v
    return best

print(find_max([3, 9, 2]))  #

def count_vowels(word):
    count = 0
    for c in word:
        if c in "aeiou":
            count += 1
    return count

